<div class="d-flex justify-content-between align-items-center mb-4"><h1><?= $staff?'Finance invoices':'My invoices'?></h1><?php if($staff):?><a class="btn btn-primary" href="<?=e(url('/finance/payments/create'))?>">Record payment</a><?php endif;?></div>
<?php if(!$invoices):?><div class="alert alert-info">No invoices found.</div><?php else:?><div class="table-responsive"><table class="table table-striped"><thead><tr><th>Invoice</th><?php if($staff):?><th>Member</th><?php endif;?><th>Issued</th><th>Total</th><th>Paid</th><th>Balance</th><th>Status</th></tr></thead><tbody><?php foreach($invoices as $i):?><tr><td><a href="<?=e(url('/finance/invoices/'.$i['invoice_number']))?>"><?=e($i['invoice_number'])?></a></td><?php if($staff):?><td><?=e($i['member_name'])?></td><?php endif;?><td><?=e($i['issued_at'])?></td><td><?=e($i['currency'].' '.$i['total'])?></td><td><?=e($i['amount_paid'])?></td><td><?=e($i['balance_due'])?></td><td><?=e(str_replace('_',' ',$i['status']))?></td></tr><?php endforeach;?></tbody></table></div><?php endif;?>
